--
-- Name: analytics_cost_aggregates(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analytics_cost_aggregates(p_workspace_id uuid DEFAULT NULL::uuid, p_workspace_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(total_tokens bigint, total_cost bigint, total_time_minutes numeric, handoff_count bigint, tasks_with_cost bigint)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    COALESCE(SUM((metadata->>'tokens_spent')::bigint), 0) AS total_tokens,
    COALESCE(SUM((metadata->>'cost_cents')::bigint), 0) AS total_cost,
    COALESCE(SUM((metadata->>'time_active_minutes')::numeric), 0) AS total_time_minutes,
    COALESCE(SUM(jsonb_array_length(CASE WHEN metadata ? 'agent_handoffs' AND jsonb_typeof(metadata->'agent_handoffs') = 'array' THEN metadata->'agent_handoffs' ELSE '[]'::jsonb END)), 0) AS handoff_count,
    COUNT(*) FILTER (WHERE
      metadata ? 'tokens_spent' OR metadata ? 'cost_cents' OR metadata ? 'time_active_minutes'
    ) AS tasks_with_cost
  FROM tasks
  WHERE status = 'done'
    AND metadata IS NOT NULL
    AND (
      (p_workspace_ids IS NOT NULL AND workspace_id = ANY(p_workspace_ids))
      OR (p_workspace_id IS NOT NULL AND workspace_id = p_workspace_id)
      OR (p_workspace_ids IS NULL AND p_workspace_id IS NULL)
    );
$$;


--
-- Name: analytics_cost_by_agent(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analytics_cost_by_agent(p_workspace_id uuid DEFAULT NULL::uuid, p_workspace_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(agent_name text, total_cost_usd numeric, input_tokens bigint, output_tokens bigint, request_count bigint)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    COALESCE(cu.agent_name, 'unknown') AS agent_name,
    SUM(cu.total_cost_usd)::numeric AS total_cost_usd,
    SUM(cu.input_tokens)::bigint AS input_tokens,
    SUM(cu.output_tokens)::bigint AS output_tokens,
    COUNT(*)::bigint AS request_count
  FROM claude_usage cu
  WHERE
    (p_workspace_ids IS NOT NULL AND cu.workspace_id = ANY(p_workspace_ids))
    OR (p_workspace_ids IS NULL AND p_workspace_id IS NOT NULL AND cu.workspace_id = p_workspace_id)
    OR (p_workspace_ids IS NULL AND p_workspace_id IS NULL)
  GROUP BY COALESCE(cu.agent_name, 'unknown')
  ORDER BY SUM(cu.total_cost_usd) DESC;
$$;


--
-- Name: analytics_cost_by_model(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analytics_cost_by_model(p_workspace_id uuid DEFAULT NULL::uuid, p_workspace_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(model text, total_cost_usd numeric, input_tokens bigint, output_tokens bigint, request_count bigint)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    cu.model,
    SUM(cu.total_cost_usd)::numeric AS total_cost_usd,
    SUM(cu.input_tokens)::bigint AS input_tokens,
    SUM(cu.output_tokens)::bigint AS output_tokens,
    COUNT(*)::bigint AS request_count
  FROM claude_usage cu
  WHERE
    (p_workspace_ids IS NOT NULL AND cu.workspace_id = ANY(p_workspace_ids))
    OR (p_workspace_ids IS NULL AND p_workspace_id IS NOT NULL AND cu.workspace_id = p_workspace_id)
    OR (p_workspace_ids IS NULL AND p_workspace_id IS NULL)
  GROUP BY cu.model
  ORDER BY SUM(cu.total_cost_usd) DESC;
$$;


--
-- Name: analytics_cost_sum(timestamp with time zone, timestamp with time zone, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analytics_cost_sum(p_since timestamp with time zone, p_until timestamp with time zone DEFAULT NULL::timestamp with time zone, p_workspace_id uuid DEFAULT NULL::uuid, p_workspace_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(total_cost numeric)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    COALESCE(SUM(total_cost_usd), 0) AS total_cost
  FROM claude_usage
  WHERE created_at >= p_since
    AND (p_until IS NULL OR created_at < p_until)
    AND (
      (p_workspace_ids IS NOT NULL AND workspace_id = ANY(p_workspace_ids))
      OR (p_workspace_id IS NOT NULL AND workspace_id = p_workspace_id)
      OR (p_workspace_ids IS NULL AND p_workspace_id IS NULL)
    );
$$;


--
-- Name: analytics_cost_trend(timestamp with time zone, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analytics_cost_trend(p_since timestamp with time zone, p_workspace_id uuid DEFAULT NULL::uuid, p_workspace_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(day date, opus numeric, sonnet numeric, haiku numeric)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    (cu.created_at AT TIME ZONE 'UTC')::date AS day,
    ROUND(SUM(CASE WHEN LOWER(cu.model) LIKE '%opus%' THEN cu.total_cost_usd ELSE 0 END)::numeric, 2) AS opus,
    ROUND(SUM(CASE WHEN LOWER(cu.model) NOT LIKE '%opus%' AND LOWER(cu.model) NOT LIKE '%haiku%' THEN cu.total_cost_usd ELSE 0 END)::numeric, 2) AS sonnet,
    ROUND(SUM(CASE WHEN LOWER(cu.model) LIKE '%haiku%' THEN cu.total_cost_usd ELSE 0 END)::numeric, 2) AS haiku
  FROM claude_usage cu
  WHERE
    cu.created_at >= p_since
    AND (
      (p_workspace_ids IS NOT NULL AND cu.workspace_id = ANY(p_workspace_ids))
      OR (p_workspace_ids IS NULL AND p_workspace_id IS NOT NULL AND cu.workspace_id = p_workspace_id)
      OR (p_workspace_ids IS NULL AND p_workspace_id IS NULL)
    )
  GROUP BY (cu.created_at AT TIME ZONE 'UTC')::date
  ORDER BY day;
$$;


--
-- Name: analytics_daily_completions(timestamp with time zone, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analytics_daily_completions(p_since timestamp with time zone, p_workspace_id uuid DEFAULT NULL::uuid, p_workspace_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(day date, count bigint)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    (completed_at AT TIME ZONE 'UTC')::date AS day,
    COUNT(*) AS count
  FROM tasks
  WHERE status = 'done'
    AND completed_at IS NOT NULL
    AND completed_at >= p_since
    AND (
      (p_workspace_ids IS NOT NULL AND workspace_id = ANY(p_workspace_ids))
      OR (p_workspace_id IS NOT NULL AND workspace_id = p_workspace_id)
      OR (p_workspace_ids IS NULL AND p_workspace_id IS NULL)
    )
  GROUP BY (completed_at AT TIME ZONE 'UTC')::date
  ORDER BY day;
$$;


--
-- Name: analytics_daily_cost(timestamp with time zone, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analytics_daily_cost(p_since timestamp with time zone, p_workspace_id uuid DEFAULT NULL::uuid, p_workspace_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(day date, total_cost numeric)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    (created_at AT TIME ZONE 'UTC')::date AS day,
    COALESCE(SUM(total_cost_usd), 0) AS total_cost
  FROM claude_usage
  WHERE created_at >= p_since
    AND (
      (p_workspace_ids IS NOT NULL AND workspace_id = ANY(p_workspace_ids))
      OR (p_workspace_id IS NOT NULL AND workspace_id = p_workspace_id)
      OR (p_workspace_ids IS NULL AND p_workspace_id IS NULL)
    )
  GROUP BY (created_at AT TIME ZONE 'UTC')::date
  ORDER BY day;
$$;


--
-- Name: analytics_overview(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analytics_overview(p_workspace_id uuid DEFAULT NULL::uuid, p_workspace_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(total bigint, in_progress bigint, done_today bigint, done_this_week bigint, overdue bigint, done_count bigint, source_breakdown jsonb)
    LANGUAGE sql STABLE
    AS $$
  WITH filtered AS (
    SELECT t.status, t.completed_at, t.due_date, COALESCE(t.source, 'web') AS src
    FROM tasks t
    WHERE
      t.status != 'archived'
      AND (
        (p_workspace_ids IS NOT NULL AND t.workspace_id = ANY(p_workspace_ids))
        OR (p_workspace_ids IS NULL AND p_workspace_id IS NOT NULL AND t.workspace_id = p_workspace_id)
        OR (p_workspace_ids IS NULL AND p_workspace_id IS NULL)
      )
  ),
  week_bounds AS (
    SELECT
      date_trunc('week', NOW())::timestamptz AS week_start,
      (date_trunc('week', NOW()) + interval '6 days 23 hours 59 minutes 59 seconds')::timestamptz AS week_end
  )
  SELECT
    COUNT(*)::bigint AS total,
    COUNT(*) FILTER (WHERE f.status = 'in_progress')::bigint AS in_progress,
    COUNT(*) FILTER (WHERE f.status = 'done' AND f.completed_at >= date_trunc('day', NOW()))::bigint AS done_today,
    COUNT(*) FILTER (WHERE f.status = 'done' AND f.completed_at >= wb.week_start AND f.completed_at <= wb.week_end)::bigint AS done_this_week,
    COUNT(*) FILTER (WHERE f.status NOT IN ('done', 'archived') AND f.due_date IS NOT NULL AND f.due_date::timestamptz < NOW())::bigint AS overdue,
    COUNT(*) FILTER (WHERE f.status = 'done')::bigint AS done_count,
    COALESCE(
      (SELECT jsonb_object_agg(src, cnt) FROM (SELECT src, COUNT(*) AS cnt FROM filtered GROUP BY src) sub),
      '{}'::jsonb
    ) AS source_breakdown
  FROM filtered f
  CROSS JOIN week_bounds wb;
$$;


--
-- Name: analytics_priorities(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analytics_priorities(p_workspace_id uuid DEFAULT NULL::uuid, p_workspace_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(priority text, count bigint)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    COALESCE(t.priority, 'normal') AS priority,
    COUNT(*)::bigint AS count
  FROM tasks t
  WHERE
    t.status = 'done'
    AND (
      (p_workspace_ids IS NOT NULL AND t.workspace_id = ANY(p_workspace_ids))
      OR (p_workspace_ids IS NULL AND p_workspace_id IS NOT NULL AND t.workspace_id = p_workspace_id)
      OR (p_workspace_ids IS NULL AND p_workspace_id IS NULL)
    )
  GROUP BY COALESCE(t.priority, 'normal');
$$;


--
-- Name: analytics_velocity(integer, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analytics_velocity(p_weeks integer DEFAULT 12, p_workspace_id uuid DEFAULT NULL::uuid, p_workspace_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(week_start date, week_end date, count bigint)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    date_trunc('week', t.completed_at AT TIME ZONE 'UTC')::date AS week_start,
    (date_trunc('week', t.completed_at AT TIME ZONE 'UTC') + interval '6 days')::date AS week_end,
    COUNT(*)::bigint AS count
  FROM tasks t
  WHERE
    t.status = 'done'
    AND t.completed_at IS NOT NULL
    AND t.completed_at >= (NOW() - (p_weeks || ' weeks')::interval)
    AND (
      (p_workspace_ids IS NOT NULL AND t.workspace_id = ANY(p_workspace_ids))
      OR (p_workspace_ids IS NULL AND p_workspace_id IS NOT NULL AND t.workspace_id = p_workspace_id)
      OR (p_workspace_ids IS NULL AND p_workspace_id IS NULL)
    )
  GROUP BY date_trunc('week', t.completed_at AT TIME ZONE 'UTC')
  ORDER BY week_start;
$$;


--
-- Name: auto_set_completed_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_set_completed_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status = 'done' AND (OLD.status IS DISTINCT FROM 'done') AND NEW.completed_at IS NULL THEN
    NEW.completed_at = now();
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: auto_unblock_dependents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_unblock_dependents() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  dep_task RECORD;
  all_done BOOLEAN;
  dep_id UUID;
  new_metadata JSONB;
BEGIN
  -- Only fire when status changes TO 'done'
  IF NEW.status = 'done' AND (OLD.status IS DISTINCT FROM 'done') THEN
    -- Find all tasks that have this task in their depends_on array
    FOR dep_task IN
      SELECT id, depends_on, status, metadata
      FROM tasks
      WHERE depends_on @> ARRAY[NEW.id]::uuid[]
        AND status NOT IN ('done', 'in_progress', 'review')
    LOOP
      -- Check if ALL dependencies for this task are now done
      all_done := TRUE;
      IF dep_task.depends_on IS NOT NULL THEN
        FOR dep_id IN SELECT unnest(dep_task.depends_on)
        LOOP
          IF NOT EXISTS (
            SELECT 1 FROM tasks WHERE id = dep_id AND status = 'done'
          ) THEN
            all_done := FALSE;
            EXIT;
          END IF;
        END LOOP;
      END IF;

      -- If all deps are done, clear blocked state
      IF all_done THEN
        new_metadata := COALESCE(dep_task.metadata, '{}'::jsonb);
        -- Safely remove blocked keys only if they exist
        IF new_metadata ? 'blocked_reason' THEN
          new_metadata := new_metadata - 'blocked_reason';
        END IF;
        IF new_metadata ? 'blocked_by' THEN
          new_metadata := new_metadata - 'blocked_by';
        END IF;
        IF new_metadata ? 'blocked_at' THEN
          new_metadata := new_metadata - 'blocked_at';
        END IF;
        IF new_metadata ? 'blocked' THEN
          new_metadata := new_metadata - 'blocked';
        END IF;

        UPDATE tasks
        SET metadata = new_metadata,
            updated_at = NOW()
        WHERE id = dep_task.id;
      END IF;
    END LOOP;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: check_file_overlap(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_file_overlap(p_project_id uuid, p_workspace_id uuid) RETURNS TABLE(conflicting_project_id uuid, conflicting_project_name text, conflicting_pr_number integer, conflicting_branch text, overlapping_files text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Verify the calling user has access to this workspace
  IF NOT EXISTS (
    SELECT 1 FROM workspace_memberships
    WHERE user_id = auth.uid() AND workspace_id = p_workspace_id
  ) AND NOT EXISTS (
    SELECT 1 FROM workspaces w
    JOIN org_memberships om ON om.org_id = w.org_id
    WHERE w.id = p_workspace_id AND om.user_id = auth.uid() AND om.role IN ('owner', 'admin')
  ) THEN
    RETURN; -- Return empty set for unauthorized callers
  END IF;

  RETURN QUERY
  WITH target_files AS (
    -- Get all files changed by the target project's active PRs
    SELECT UNNEST(pp.files_changed) AS file_path
    FROM project_prs pp
    WHERE pp.project_id = p_project_id
      AND pp.workspace_id = p_workspace_id
      AND pp.status IN ('draft', 'open')
  ),
  other_prs AS (
    -- Get all active PRs from OTHER projects in the same workspace
    SELECT pp.project_id, pp.pr_number, pp.branch_name, pp.files_changed
    FROM project_prs pp
    WHERE pp.workspace_id = p_workspace_id
      AND pp.project_id != p_project_id
      AND pp.status IN ('draft', 'open')
      AND array_length(pp.files_changed, 1) > 0
  )
  SELECT
    op.project_id AS conflicting_project_id,
    p.name AS conflicting_project_name,
    op.pr_number AS conflicting_pr_number,
    op.branch_name AS conflicting_branch,
    ARRAY(
      SELECT DISTINCT tf.file_path
      FROM target_files tf
      WHERE tf.file_path = ANY(op.files_changed)
    ) AS overlapping_files
  FROM other_prs op
  JOIN projects p ON p.id = op.project_id
  WHERE EXISTS (
    SELECT 1
    FROM target_files tf
    WHERE tf.file_path = ANY(op.files_changed)
  );
END;
$$;


--
-- Name: FUNCTION check_file_overlap(p_project_id uuid, p_workspace_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_file_overlap(p_project_id uuid, p_workspace_id uuid) IS 'Detects file-level overlaps between a project''s active PRs and other active PRs in the same workspace. Used for merge conflict early warning. SECURITY DEFINER needed to bypass RLS for cross-project comparison filtered by workspace_id.';


--
-- Name: check_memory_quota(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_memory_quota() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_plan text;
  v_count integer;
  v_limit integer;
BEGIN
  v_plan := 'build';
  v_limit := 500;

  SELECT COUNT(*) INTO v_count
  FROM agent_memory
  WHERE user_id = NEW.user_id;

  IF v_count >= v_limit THEN
    RAISE EXCEPTION 'Memory quota exceeded: % of % memories (plan: %). Upgrade your plan or delete old memories.',
      v_count, v_limit, v_plan;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: cleanup_expired_memories(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_expired_memories() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH deleted AS (
    DELETE FROM agent_memory
    WHERE expires_at IS NOT NULL AND expires_at < now()
    RETURNING id
  )
  SELECT COUNT(*)::integer FROM deleted;
$$;


--
-- Name: cleanup_rate_limits(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_rate_limits() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  DELETE FROM rate_limits
  WHERE window_start + (window_ms || ' milliseconds')::interval < now();
END;
$$;


--
-- Name: FUNCTION cleanup_rate_limits(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cleanup_rate_limits() IS 'Deletes expired rate limit windows. SECURITY DEFINER because RLS is enabled and no user-facing policies exist.';


--
-- Name: cleanup_ward_fix_log(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_ward_fix_log(ttl_hours integer DEFAULT 1) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  deleted INTEGER;
BEGIN
  DELETE FROM ward_fix_log
  WHERE created_at < now() - (ttl_hours || ' hours')::INTERVAL;
  GET DIAGNOSTICS deleted = ROW_COUNT;
  RETURN deleted;
END;
$$;


--
-- Name: FUNCTION cleanup_ward_fix_log(ttl_hours integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cleanup_ward_fix_log(ttl_hours integer) IS 'Purge expired WARD dedup entries. Called by cron to keep the table small.';


--
-- Name: exec_sql(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.exec_sql(query text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result json;
BEGIN
  EXECUTE query;
  result := json_build_object('success', true);
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: find_contradictions(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_contradictions(p_workspace_id uuid, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  contradictions jsonb := '[]'::jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(row_data), '[]'::jsonb)
  INTO contradictions
  FROM (
    SELECT jsonb_build_object(
      'relation_id', mr.id,
      'memory_a', jsonb_build_object('id', a.id, 'key', a.key, 'content', LEFT(a.content, 300), 'category', a.category, 'created_at', a.created_at),
      'memory_b', jsonb_build_object('id', b.id, 'key', b.key, 'content', LEFT(b.content, 300), 'category', b.category, 'created_at', b.created_at),
      'confidence', mr.confidence,
      'is_auto_detected', mr.is_auto_detected
    ) as row_data
    FROM public.memory_relations mr
    JOIN public.agent_memory a ON a.id = mr.memory_id
    JOIN public.agent_memory b ON b.id = mr.related_id
    WHERE mr.relation_type = 'contradicts'
      AND mr.workspace_id = p_workspace_id
    ORDER BY mr.confidence DESC, mr.created_at DESC
    LIMIT p_limit
  ) sub;

  RETURN contradictions;
END;
$$;


--
-- Name: get_child_workspace_ids(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_child_workspace_ids(main_ws_id uuid) RETURNS uuid[]
    LANGUAGE sql STABLE
    AS $$
  SELECT COALESCE(array_agg(id), '{}')
  FROM workspaces
  WHERE parent_workspace_id = main_ws_id;
$$;


