-- Name: get_dot_voter_room_by_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_dot_voter_room_by_token(p_share_token text) RETURNS TABLE(room_id uuid, title text, description text, status public.dot_voter_room_status, dot_limit integer, anonymous_voting boolean, allow_guest_votes boolean, item_id uuid, item_title text, item_description text, item_sort_order integer)
    LANGUAGE sql SECURITY DEFINER
