$$;


--
-- Name: get_employed_agents(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_employed_agents(p_workspace_id uuid) RETURNS TABLE(agent_id text, display_name text, role text, agent_type text, is_lead boolean, is_active boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH org_workspaces AS (
    -- Get all workspace IDs in the same org as the target workspace
    SELECT w2.id
    FROM workspaces w1
    JOIN workspaces w2 ON w1.org_id = w2.org_id
    WHERE w1.id = p_workspace_id
  ),
  -- Source of truth: earliest config per agent_id across org
  source_configs AS (
    SELECT DISTINCT ON (ac.agent_id)
      ac.agent_id,
      ac.display_name,
      ac.role,
      ac.agent_type,
      ac.is_lead
    FROM agent_configs ac
    WHERE ac.workspace_id IN (SELECT id FROM org_workspaces)
    ORDER BY ac.agent_id, ac.created_at ASC
  ),
  -- Per-workspace employment status
  local_status AS (
    SELECT ac.agent_id, ac.is_active
    FROM agent_configs ac
    WHERE ac.workspace_id = p_workspace_id
  )
  SELECT
    sc.agent_id,
    sc.display_name,
    sc.role,
    sc.agent_type,
    sc.is_lead,
    CASE
      WHEN sc.is_lead THEN true                          -- Lead agents always employed
      WHEN ls.agent_id IS NOT NULL THEN ls.is_active     -- Use workspace-local status
      ELSE false                                          -- No local record = not employed
    END AS is_active
  FROM source_configs sc
  LEFT JOIN local_status ls ON sc.agent_id = ls.agent_id
  WHERE
    sc.is_lead = true
    OR (ls.agent_id IS NOT NULL AND ls.is_active = true)
$$;


--
-- Name: get_invitation_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_invitation_user(p_user_id uuid) RETURNS TABLE(id uuid, email text, invited_at timestamp with time zone, confirmed_at timestamp with time zone, invited_role text, banned_until timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    u.id,
    u.email,
    u.invited_at,
    u.email_confirmed_at   AS confirmed_at,
    (u.raw_user_meta_data->>'invited_role')::text AS invited_role,
    u.banned_until
  FROM auth.users u
  WHERE u.id = p_user_id
    AND (
      auth.role() = 'service_role'
      OR EXISTS (
        -- Legacy path with deactivation guard
        SELECT 1 FROM org_memberships om
        WHERE om.user_id = u.id
          AND om.org_id IN (
            SELECT org_id FROM org_memberships WHERE user_id = auth.uid()
          )
          AND NOT EXISTS (
            SELECT 1 FROM org_members deact
            WHERE deact.user_id = auth.uid()
              AND deact.org_id = om.org_id
              AND deact.is_active = false
          )
      )
      OR EXISTS (
        SELECT 1 FROM org_members om
        WHERE om.user_id = u.id
          AND om.is_active = true
          AND om.org_id IN (
            SELECT org_id FROM org_members WHERE user_id = auth.uid() AND is_active = true
          )
      )
    );
$$;


--
-- Name: get_memory_context(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_memory_context(p_memory_id uuid, p_workspace_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  seed_memory jsonb;
  related_memories jsonb := '[]'::jsonb;
BEGIN
  -- Get seed memory
  SELECT jsonb_build_object(
    'id', am.id, 'key', am.key, 'category', am.category,
    'content', am.content, 'tags', am.tags, 'source', am.source,
    'importance_score', am.importance_score, 'created_at', am.created_at
  ) INTO seed_memory
  FROM public.agent_memory am
  WHERE am.id = p_memory_id AND am.workspace_id = p_workspace_id;

  IF seed_memory IS NULL THEN RETURN NULL; END IF;

  -- Get 1-hop related memories with relation metadata
  SELECT COALESCE(jsonb_agg(row_data ORDER BY confidence DESC), '[]'::jsonb)
  INTO related_memories
  FROM (
    -- Forward relations
    SELECT jsonb_build_object(
      'id', am.id, 'key', am.key, 'category', am.category,
      'content', LEFT(am.content, 500), 'relation_type', mr.relation_type::text,
      'confidence', mr.confidence, 'direction', 'outgoing'
    ) as row_data, mr.confidence
    FROM public.memory_relations mr
    JOIN public.agent_memory am ON am.id = mr.related_id
    WHERE mr.memory_id = p_memory_id
      AND mr.related_type = 'memory'
      AND mr.workspace_id = p_workspace_id
    UNION ALL
    -- Reverse relations
    SELECT jsonb_build_object(
      'id', am.id, 'key', am.key, 'category', am.category,
      'content', LEFT(am.content, 500), 'relation_type', mr.relation_type::text,
      'confidence', mr.confidence, 'direction', 'incoming'
    ) as row_data, mr.confidence
    FROM public.memory_relations mr
    JOIN public.agent_memory am ON am.id = mr.memory_id
    WHERE mr.related_id = p_memory_id
      AND mr.related_type = 'memory'
      AND mr.workspace_id = p_workspace_id
  ) sub;

  RETURN jsonb_build_object('memory', seed_memory, 'related', related_memories);
END;
$$;


--
-- Name: get_memory_graph(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_memory_graph(p_memory_id uuid, p_depth integer DEFAULT 2, p_workspace_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  result jsonb;
  visited uuid[] := ARRAY[p_memory_id];
  frontier uuid[] := ARRAY[p_memory_id];
  next_frontier uuid[];
  current_depth int := 0;
  nodes jsonb := '[]'::jsonb;
  edges jsonb := '[]'::jsonb;
BEGIN
  -- Cap depth to prevent runaway traversal
  IF p_depth > 5 THEN p_depth := 5; END IF;

  -- Add seed node
  SELECT nodes || jsonb_build_array(jsonb_build_object(
    'id', am.id, 'key', am.key, 'category', am.category,
    'content', LEFT(am.content, 200), 'importance_score', am.importance_score,
    'created_at', am.created_at, 'depth', 0
  ))
  INTO nodes
  FROM public.agent_memory am
  WHERE am.id = p_memory_id
    AND (p_workspace_id IS NULL OR am.workspace_id = p_workspace_id);

  -- BFS traversal
  WHILE current_depth < p_depth AND array_length(frontier, 1) > 0 LOOP
    current_depth := current_depth + 1;
    next_frontier := '{}';

    -- Forward edges: memory_id IN frontier
    FOR result IN
      SELECT jsonb_build_object(
        'source', mr.memory_id, 'target', mr.related_id,
        'relation_type', mr.relation_type::text, 'confidence', mr.confidence,
        'is_auto_detected', mr.is_auto_detected
      ) as edge,
      mr.related_id as next_id,
      am.id, am.key, am.category, LEFT(am.content, 200) as content_preview,
      am.importance_score, am.created_at
      FROM public.memory_relations mr
      LEFT JOIN public.agent_memory am ON am.id = mr.related_id
      WHERE mr.memory_id = ANY(frontier)
        AND mr.related_type = 'memory'
        AND NOT (mr.related_id = ANY(visited))
        AND (p_workspace_id IS NULL OR mr.workspace_id = p_workspace_id)
    LOOP
      edges := edges || jsonb_build_array(result.edge);
      IF result.id IS NOT NULL THEN
        nodes := nodes || jsonb_build_array(jsonb_build_object(
          'id', result.id, 'key', result.key, 'category', result.category,
          'content', result.content_preview, 'importance_score', result.importance_score,
          'created_at', result.created_at, 'depth', current_depth
        ));
        visited := array_append(visited, result.next_id);
        next_frontier := array_append(next_frontier, result.next_id);
      END IF;
    END LOOP;

    -- Reverse edges: related_id IN frontier (memory-to-memory only)
    FOR result IN
      SELECT jsonb_build_object(
        'source', mr.memory_id, 'target', mr.related_id,
        'relation_type', mr.relation_type::text, 'confidence', mr.confidence,
        'is_auto_detected', mr.is_auto_detected
      ) as edge,
      mr.memory_id as next_id,
      am.id, am.key, am.category, LEFT(am.content, 200) as content_preview,
      am.importance_score, am.created_at
      FROM public.memory_relations mr
      LEFT JOIN public.agent_memory am ON am.id = mr.memory_id
      WHERE mr.related_id = ANY(frontier)
        AND mr.related_type = 'memory'
        AND NOT (mr.memory_id = ANY(visited))
        AND (p_workspace_id IS NULL OR mr.workspace_id = p_workspace_id)
    LOOP
      edges := edges || jsonb_build_array(result.edge);
      IF result.id IS NOT NULL THEN
        nodes := nodes || jsonb_build_array(jsonb_build_object(
          'id', result.id, 'key', result.key, 'category', result.category,
          'content', result.content_preview, 'importance_score', result.importance_score,
          'created_at', result.created_at, 'depth', current_depth
        ));
        visited := array_append(visited, result.next_id);
        next_frontier := array_append(next_frontier, result.next_id);
      END IF;
    END LOOP;

    frontier := next_frontier;
  END LOOP;

  RETURN jsonb_build_object('nodes', nodes, 'edges', edges);
END;
$$;


--
-- Name: get_memory_ttl_days(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_memory_ttl_days(p_workspace_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_plan text;
BEGIN
  SELECT COALESCE(s.plan, 'build') INTO v_plan
  FROM workspace_memberships wm
  LEFT JOIN subscriptions s ON s.user_id = wm.user_id
  WHERE wm.workspace_id = p_workspace_id
    AND wm.role = 'owner'
  LIMIT 1;

  IF v_plan IS NULL THEN
    v_plan := 'build';
  END IF;

  RETURN CASE v_plan
    WHEN 'build' THEN 90
    WHEN 'pro' THEN 365
    WHEN 'team' THEN -1  -- no expiry
    WHEN 'enterprise' THEN -1
    WHEN 'platform_owner' THEN -1
    WHEN 'sponsored' THEN -1
    ELSE 90
  END;
END;
$$;


--
-- Name: get_pending_invitations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pending_invitations() RETURNS TABLE(id uuid, email text, invited_at timestamp with time zone, created_at timestamp with time zone, invited_role text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT DISTINCT
    u.id,
    u.email,
    u.invited_at,
    u.created_at,
    (u.raw_user_meta_data->>'invited_role')::text AS invited_role
  FROM auth.users u
  WHERE u.invited_at IS NOT NULL
    AND u.email_confirmed_at IS NULL
    AND (
      auth.role() = 'service_role'
      OR EXISTS (
        -- Legacy path with deactivation guard
        SELECT 1 FROM org_memberships om
        WHERE om.user_id = u.id
          AND om.org_id IN (
            SELECT org_id FROM org_memberships WHERE user_id = auth.uid()
          )
          AND NOT EXISTS (
            SELECT 1 FROM org_members deact
            WHERE deact.user_id = auth.uid()
              AND deact.org_id = om.org_id
              AND deact.is_active = false
          )
      )
      OR EXISTS (
        SELECT 1 FROM org_members om
        WHERE om.user_id = u.id
          AND om.is_active = true
          AND om.org_id IN (
            SELECT org_id FROM org_members WHERE user_id = auth.uid() AND is_active = true
          )
      )
    );
$$;


--
-- Name: get_supersession_chain(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_supersession_chain(p_key text, p_workspace_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  chain jsonb := '[]'::jsonb;
BEGIN
  -- Find all memories with this key, ordered by version/creation time
  -- Include supersedes relations to show the chain
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', am.id, 'key', am.key, 'content', LEFT(am.content, 300),
    'version', am.version, 'created_at', am.created_at, 'is_archived', am.is_archived,
    'superseded_by', (
      SELECT mr.related_id FROM public.memory_relations mr
      WHERE mr.memory_id = am.id AND mr.relation_type = 'supersedes'
        AND mr.related_type = 'memory' AND mr.workspace_id = p_workspace_id
      LIMIT 1
    )
  ) ORDER BY am.created_at ASC), '[]'::jsonb)
  INTO chain
  FROM public.agent_memory am
  WHERE am.key = p_key AND am.workspace_id = p_workspace_id;

  RETURN chain;
END;
$$;


--
-- Name: get_users_by_ids(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_users_by_ids(user_ids uuid[]) RETURNS TABLE(id uuid, email text, display_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT DISTINCT
    u.id,
    u.email,
    (u.raw_user_meta_data->>'display_name')::text AS display_name
  FROM auth.users u
  WHERE u.id = ANY(user_ids)
    AND (
      -- service_role bypass (explicit role check, not auth.uid() IS NULL)
      auth.role() = 'service_role'
      OR EXISTS (
        -- Legacy path: org_memberships (no is_active column).
        -- Exclude users explicitly deactivated in org_members to prevent bypass.
        SELECT 1
        FROM org_memberships caller_om
        JOIN org_memberships target_om ON caller_om.org_id = target_om.org_id
        WHERE caller_om.user_id = auth.uid()
          AND target_om.user_id = u.id
          AND NOT EXISTS (
            SELECT 1 FROM org_members deact
            WHERE deact.user_id = auth.uid()
              AND deact.org_id = caller_om.org_id
              AND deact.is_active = false
          )
      )
      OR EXISTS (
        -- RBAC v2 path: org_members with is_active enforcement
        SELECT 1
        FROM org_members caller_om
        JOIN org_members target_om ON caller_om.org_id = target_om.org_id
        WHERE caller_om.user_id = auth.uid()
          AND caller_om.is_active = true
          AND target_om.user_id = u.id
          AND target_om.is_active = true
      )
    );
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _role public.user_role;
  _invited_role text;
  _org_id uuid;
  _workspace_id uuid;
  _user_name text;
  _slug text;
  _role_id uuid;
BEGIN
  -- 1. Determine role from invitation metadata or default to member
  _invited_role := NEW.raw_user_meta_data->>'invited_role';
  BEGIN
    _role := _invited_role::public.user_role;
  EXCEPTION WHEN invalid_text_representation THEN
    _role := 'member';
  END;
  IF _role IS NULL THEN
    _role := 'member';
  END IF;

  -- 2. Insert/update user_roles (may be updated to 'owner' below for self-signup)
  INSERT INTO public.user_roles (user_id, role)
  VALUES (NEW.id, _role)
  ON CONFLICT (user_id) DO UPDATE SET role = EXCLUDED.role;

  -- 3. Build a display name and slug from email
  _user_name := split_part(NEW.email, '@', 1);
  _slug := lower(regexp_replace(_user_name, '[^a-zA-Z0-9]', '-', 'g'));
  _slug := _slug || '-' || substr(gen_random_uuid()::text, 1, 4);

  -- 4. Check if this is an invited user (has invitation pending)
  SELECT org_id INTO _org_id
  FROM public.org_memberships
  WHERE user_id = NEW.id
  LIMIT 1;

  IF _org_id IS NOT NULL THEN
    -- Invited user: org_membership was pre-created by invite flow.
    UPDATE public.user_roles SET org_id = _org_id WHERE user_id = NEW.id;

    -- Resolve RBAC role_id from invitation role
    SELECT id INTO _role_id FROM public.roles WHERE slug = _invited_role LIMIT 1;
    IF _role_id IS NULL THEN
      SELECT id INTO _role_id FROM public.roles WHERE slug = 'member' LIMIT 1;
    END IF;

    -- Also create org_members row for RBAC v2
    INSERT INTO public.org_members (user_id, org_id, role_id, is_owner, is_active)
    VALUES (NEW.id, _org_id, _role_id, false, true)
    ON CONFLICT DO NOTHING;

    -- Add to default workspace of that org
    SELECT id INTO _workspace_id
    FROM public.workspaces
    WHERE org_id = _org_id AND is_default = true
    LIMIT 1;

    IF _workspace_id IS NOT NULL THEN
      INSERT INTO public.workspace_memberships (user_id, workspace_id)
      VALUES (NEW.id, _workspace_id)
      ON CONFLICT (user_id, workspace_id) DO NOTHING;
    END IF;
  ELSE
    -- Self-signup: create org + workspace + memberships
    INSERT INTO public.organizations (name, slug, owner_id)
    VALUES (_user_name || '''s Org', _slug, NEW.id)
    RETURNING id INTO _org_id;

    -- Create org_membership as owner (legacy)
    INSERT INTO public.org_memberships (org_id, user_id, role)
    VALUES (_org_id, NEW.id, 'owner')
    ON CONFLICT DO NOTHING;

    -- Create org_members row for RBAC v2
    SELECT id INTO _role_id FROM public.roles WHERE slug = 'owner' LIMIT 1;
    INSERT INTO public.org_members (user_id, org_id, role_id, is_owner, is_active)
    VALUES (NEW.id, _org_id, _role_id, true, true)
    ON CONFLICT DO NOTHING;

    -- Update user_roles with org_id AND set role to 'owner' (self-signup = org creator)
    UPDATE public.user_roles SET org_id = _org_id, role = 'owner' WHERE user_id = NEW.id;

    -- Create default workspace
    INSERT INTO public.workspaces (org_id, name, slug, is_default)
    VALUES (_org_id, 'Main', _slug || '-main', true)
    RETURNING id INTO _workspace_id;

    -- Create workspace_membership
    INSERT INTO public.workspace_memberships (user_id, workspace_id)
    VALUES (NEW.id, _workspace_id)
    ON CONFLICT (user_id, workspace_id) DO NOTHING;
  END IF;

  -- 5. Log provisioning
  BEGIN
    INSERT INTO public.activity_log (event_type, severity, source, title, actor_user_id, workspace_id)
    VALUES (
      'user.provisioned',
      'info',
      'system',
      'User auto-provisioned: ' || NEW.email,
      NEW.id,
      _workspace_id
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN NEW;
END;
$$;


--
-- Name: hybrid_brain_search(extensions.vector, text, uuid, integer, double precision, double precision, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hybrid_brain_search(query_embedding extensions.vector, query_text text, filter_workspace_id uuid, match_count integer DEFAULT 20, p_vector_weight double precision DEFAULT 0.7, p_keyword_weight double precision DEFAULT 0.3, filter_category text DEFAULT NULL::text, filter_source text DEFAULT NULL::text, p_include_archived boolean DEFAULT false) RETURNS TABLE(id uuid, key text, content text, abstract character varying, category text, source text, tags text, memory_type text, importance_score double precision, vector_similarity double precision, keyword_rank double precision, combined_score double precision, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  ts_query tsquery;
BEGIN
  -- Enable iterative scan for RLS compatibility with HNSW
  SET LOCAL hnsw.iterative_scan = 'relaxed_order';
  SET LOCAL hnsw.max_scan_tuples = 20000;

  -- Convert query text to tsquery; if it fails, use NULL (vector-only fallback)
  BEGIN
    ts_query := plainto_tsquery('english', query_text);
  EXCEPTION WHEN OTHERS THEN
    ts_query := NULL;
  END;

  RETURN QUERY
  WITH vector_results AS (
    -- Phase 1: Get top candidates from vector search (cast wide net)
    SELECT
      am.id,
      am.key,
      am.content,
      am.abstract,
      am.category,
      am.source,
      am.tags,
      am.memory_type,
      am.importance_score,
      am.fts,
      1 - (am.embedding <=> query_embedding) AS vec_sim,
      am.created_at,
      am.updated_at
    FROM agent_memory am
    WHERE am.embedding IS NOT NULL
      AND am.workspace_id = filter_workspace_id
      AND (p_include_archived OR NOT COALESCE(am.is_archived, false))
      AND (filter_category IS NULL OR am.category = filter_category)
      AND (filter_source IS NULL OR am.source = filter_source)
      AND 1 - (am.embedding <=> query_embedding) > 0.3  -- wider threshold for blending
    ORDER BY am.embedding <=> query_embedding
    LIMIT match_count * 3  -- over-fetch for re-ranking
  ),
  keyword_results AS (
    -- Phase 2: Get keyword matches (only if tsquery is valid)
    SELECT
      am.id,
      ts_rank_cd(am.fts, ts_query, 32) AS kw_rank  -- normalization: rank / (1 + rank)
    FROM agent_memory am
    WHERE ts_query IS NOT NULL
      AND am.fts @@ ts_query
      AND am.workspace_id = filter_workspace_id
      AND (p_include_archived OR NOT COALESCE(am.is_archived, false))
      AND (filter_category IS NULL OR am.category = filter_category)
      AND (filter_source IS NULL OR am.source = filter_source)
    LIMIT match_count * 3
  ),
  combined AS (
    -- Phase 3: Merge and score
    SELECT
      vr.id,
      vr.key,
      vr.content,
      vr.abstract,
      vr.category,
      vr.source,
      vr.tags,
      vr.memory_type,
      vr.importance_score,
      vr.vec_sim,
      COALESCE(kr.kw_rank, 0.0) AS kw_rank,
      -- Normalize keyword rank to 0-1 range (ts_rank_cd with norm=32 is already 0-1ish)
      -- Combined score: weighted blend of vector similarity and keyword rank
      (vr.vec_sim * p_vector_weight)
        + (COALESCE(kr.kw_rank, 0.0) * p_keyword_weight)
        + (COALESCE(vr.importance_score, 0.5) * 0.1)  -- small importance boost
      AS combo_score,
      vr.created_at,
      vr.updated_at
    FROM vector_results vr
    LEFT JOIN keyword_results kr ON kr.id = vr.id

    UNION ALL

    -- Include keyword-only matches (no vector hit but strong keyword match)
    SELECT
      am.id,
      am.key,
      am.content,
      am.abstract,
      am.category,
      am.source,
      am.tags,
      am.memory_type,
      am.importance_score,
      0.0 AS vec_sim,
      kr.kw_rank,
      (kr.kw_rank * p_keyword_weight) + (COALESCE(am.importance_score, 0.5) * 0.1) AS combo_score,
      am.created_at,
      am.updated_at
    FROM keyword_results kr
    JOIN agent_memory am ON am.id = kr.id
    WHERE kr.id NOT IN (SELECT vr2.id FROM vector_results vr2)
  )
  SELECT
    c.id,
    c.key,
    c.content,
    c.abstract,
    c.category,
    c.source,
    c.tags,
    c.memory_type,
    c.importance_score,
    c.vec_sim AS vector_similarity,
    c.kw_rank AS keyword_rank,
    c.combo_score AS combined_score,
    c.created_at,
    c.updated_at
  FROM combined c
  ORDER BY c.combo_score DESC
  LIMIT match_count;
END;
$$;


--
-- Name: FUNCTION hybrid_brain_search(query_embedding extensions.vector, query_text text, filter_workspace_id uuid, match_count integer, p_vector_weight double precision, p_keyword_weight double precision, filter_category text, filter_source text, p_include_archived boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.hybrid_brain_search(query_embedding extensions.vector, query_text text, filter_workspace_id uuid, match_count integer, p_vector_weight double precision, p_keyword_weight double precision, filter_category text, filter_source text, p_include_archived boolean) IS 'Hybrid search combining pgvector cosine similarity with PostgreSQL tsvector keyword ranking. Returns results scored by weighted blend of semantic meaning and exact term matches.';


--
-- Name: increment_referral_count(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_referral_count(p_referral_code text, p_threshold integer DEFAULT 2) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  -- Atomic increment + priority upgrade
  UPDATE public.waitlist
  SET referral_count = referral_count + 1,
      priority = CASE WHEN referral_count + 1 >= p_threshold THEN true ELSE priority END,
      updated_at = now()
  WHERE referral_code = p_referral_code;
END;
$$;


--
-- Name: increment_trial_tokens(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_trial_tokens(p_workspace_id uuid, p_tokens integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Guard against negative increments (would grant free tokens)
  IF p_tokens <= 0 THEN RETURN; END IF;

  UPDATE workspaces
  SET trial_tokens_used = LEAST(
    trial_tokens_used + p_tokens,
    trial_token_budget
  )
  WHERE id = p_workspace_id;
END;
$$;


--
-- Name: is_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_owner() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = auth.uid() AND role = 'owner' AND is_active = true
  ) OR EXISTS (
    SELECT 1 FROM public.org_members
    WHERE user_id = auth.uid() AND is_owner = true AND is_active = true
  );
$$;


--
-- Name: match_memories(extensions.vector, double precision, integer, text, text, uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_memories(query_embedding extensions.vector, match_threshold double precision DEFAULT 0.5, match_count integer DEFAULT 20, filter_source text DEFAULT NULL::text, filter_category text DEFAULT NULL::text, filter_org_id uuid DEFAULT NULL::uuid, filter_workspace_id uuid DEFAULT NULL::uuid, filter_user_id uuid DEFAULT NULL::uuid, p_include_archived boolean DEFAULT false) RETURNS TABLE(id uuid, key text, content text, abstract character varying, category text, source text, tags text, memory_type text, agent_id text, importance_score double precision, similarity double precision, hotness_score double precision, final_score double precision, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Enable iterative scan for RLS compatibility with HNSW
  SET LOCAL hnsw.iterative_scan = 'relaxed_order';
  SET LOCAL hnsw.max_scan_tuples = 20000;

  RETURN QUERY
  SELECT
    am.id,
    am.key,
    am.content,
    am.abstract,
    am.category,
    am.source,
    am.tags,
    am.memory_type,
    am.agent_id,
    am.importance_score,
    1 - (am.embedding <=> query_embedding) AS similarity,
    -- Hotness: sigmoid of access count * exponential decay (7-day half-life), floor at 0.05
    GREATEST(0.05,
      (1.0 / (1.0 + exp(-ln(1.0 + COALESCE(am.access_count, 0)))))
      * exp(-0.693 * EXTRACT(EPOCH FROM (now() - COALESCE(am.updated_at, am.created_at))) / 604800.0)
    ) AS hotness_score,
    -- Final blended score: 60% similarity + 20% hotness + 20% importance
    (1 - (am.embedding <=> query_embedding)) * 0.6
    + GREATEST(0.05,
        (1.0 / (1.0 + exp(-ln(1.0 + COALESCE(am.access_count, 0)))))
        * exp(-0.693 * EXTRACT(EPOCH FROM (now() - COALESCE(am.updated_at, am.created_at))) / 604800.0)
      ) * 0.2
    + COALESCE(am.importance_score, 0.5) * 0.2
    AS final_score,
    am.created_at,
    am.updated_at
  FROM agent_memory am
  WHERE am.embedding IS NOT NULL
    AND 1 - (am.embedding <=> query_embedding) > match_threshold
    AND (p_include_archived OR NOT COALESCE(am.is_archived, false))
    AND (filter_user_id IS NULL OR am.user_id = filter_user_id)
    AND (filter_source IS NULL OR am.source = filter_source)
    AND (filter_category IS NULL OR am.category = filter_category)
    AND (filter_org_id IS NULL OR am.org_id = filter_org_id)
    AND (filter_workspace_id IS NULL OR am.workspace_id = filter_workspace_id)
  ORDER BY final_score DESC
  LIMIT match_count;
END;
$$;


--
-- Name: org_staff_org_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_staff_org_ids() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT om.org_id
  FROM org_members om
  JOIN roles r ON r.id = om.role_id
  WHERE om.user_id = auth.uid()
    AND om.is_active = true
    AND (om.is_owner = true OR r.slug = 'admin');
$$;


--
-- Name: prevent_org_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_org_deletion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  task_count integer;
  workspace_count integer;
BEGIN
  SELECT count(*) INTO task_count FROM tasks WHERE org_id = OLD.id;
  SELECT count(*) INTO workspace_count FROM workspaces WHERE org_id = OLD.id;

  IF task_count > 0 THEN
    RAISE EXCEPTION 'Cannot delete organization with % tasks. Transfer or delete tasks first.', task_count;
  END IF;

  IF workspace_count > 1 THEN
    RAISE EXCEPTION 'Cannot delete organization with % workspaces. Delete workspaces first.', workspace_count;
  END IF;

  RETURN OLD;
END;
$$;


--
-- Name: publish_vault_memories(uuid[], uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_vault_memories(p_memory_ids uuid[], p_workspace_id uuid, p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
-- SECURITY DEFINER needed: merges metadata JSONB server-side in one query
-- instead of N individual updates. Scoped by workspace_id + source filter.
DECLARE
  updated_count int;
BEGIN
  UPDATE agent_memory
  SET
    metadata = metadata || jsonb_build_object(
      'published', true,
      'published_at', now()::text,
      'published_by', p_user_id::text
    ),
    updated_at = now()
  WHERE id = ANY(p_memory_ids)
    AND workspace_id = p_workspace_id
    AND source = 'vault-sync';

  GET DIAGNOSTICS updated_count = ROW_COUNT;
  RETURN updated_count;
END;
$$;


--
-- Name: rate_limit_check(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rate_limit_check(p_key text, p_window_ms integer) RETURNS TABLE(out_count integer, out_window_start timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  INSERT INTO rate_limits (key, count, window_start, window_ms)
  VALUES (p_key, 1, now(), p_window_ms)
  ON CONFLICT (key) DO UPDATE SET
    count = CASE
      WHEN rate_limits.window_start + (rate_limits.window_ms || ' milliseconds')::interval < now()
      THEN 1
      ELSE rate_limits.count + 1
    END,
    window_start = CASE
      WHEN rate_limits.window_start + (rate_limits.window_ms || ' milliseconds')::interval < now()
      THEN now()
      ELSE rate_limits.window_start
    END,
    window_ms = p_window_ms,
    updated_at = now()
  RETURNING rate_limits.count, rate_limits.window_start;
END;
$$;


--
-- Name: FUNCTION rate_limit_check(p_key text, p_window_ms integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rate_limit_check(p_key text, p_window_ms integer) IS 'Atomic rate limit check via upsert. SECURITY DEFINER because RLS is enabled with no user-facing policies.';


--
-- Name: resolve_user_permissions(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_user_permissions(p_user_id uuid, p_workspace_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_legacy_role    text;
  v_legacy_active  boolean;
  v_org_id         uuid;
  v_is_owner       boolean := false;
  v_is_active      boolean;
  v_role_id        uuid;
  v_role_slug      text;
  v_permission_keys text[];
BEGIN
  -- Step 1: Platform admin check (legacy user_roles bridge)
  SELECT role, is_active INTO v_legacy_role, v_legacy_active
  FROM user_roles
  WHERE user_id = p_user_id
  LIMIT 1;

  -- Deactivated user → deny all
  IF v_legacy_active = false THEN
    RETURN jsonb_build_object(
      'is_platform_owner', false,
      'is_owner', false,
      'is_active', false,
      'role_slug', null,
      'permission_keys', '[]'::jsonb
    );
  END IF;

  -- Platform admin (owner in user_roles) → grant all
  IF v_legacy_role = 'owner' THEN
    RETURN jsonb_build_object(
      'is_platform_owner', true,
      'is_owner', true,
      'is_active', true,
      'role_slug', null,
      'permission_keys', (
        SELECT jsonb_agg(key) FROM permissions
      )
    );
  END IF;

  -- Step 1b: No workspace context → check org ownership first, then legacy role fallback
  IF p_workspace_id IS NULL THEN
    -- Check if user is owner of ANY org
    SELECT om.is_owner, om.is_active, om.role_id
    INTO v_is_owner, v_is_active, v_role_id
    FROM org_members om
    WHERE om.user_id = p_user_id AND om.is_owner = true
    LIMIT 1;

    IF v_is_owner THEN
      IF v_is_active = false THEN
        RETURN jsonb_build_object(
          'is_platform_owner', false,
          'is_owner', false,
          'is_active', false,
          'role_slug', null,
          'permission_keys', '[]'::jsonb
        );
      END IF;

      SELECT r.slug INTO v_role_slug FROM roles r WHERE r.id = v_role_id;
      RETURN jsonb_build_object(
        'is_platform_owner', false,
        'is_owner', true,
        'is_active', true,
        'role_slug', v_role_slug,
        'permission_keys', (
          SELECT jsonb_agg(key) FROM permissions
        )
      );
    END IF;

    -- Legacy role fallback
    IF v_legacy_role IS NOT NULL THEN
      SELECT array_agg(p.key) INTO v_permission_keys
      FROM role_permissions rp
      JOIN permissions p ON p.id = rp.permission_id
      JOIN roles r ON r.id = rp.role_id
      WHERE r.slug = v_legacy_role AND r.is_system = true;

      RETURN jsonb_build_object(
        'is_platform_owner', false,
        'is_owner', false,
        'is_active', true,
        'role_slug', v_legacy_role,
        'permission_keys', COALESCE(to_jsonb(v_permission_keys), '[]'::jsonb)
      );
    END IF;

    -- No workspace, no org ownership, no legacy role → default deny
    RETURN jsonb_build_object(
      'is_platform_owner', false,
      'is_owner', false,
      'is_active', true,
      'role_slug', null,
      'permission_keys', '[]'::jsonb
    );
  END IF;

  -- Step 2: Resolve workspace → org_id
  IF p_workspace_id IS NOT NULL THEN
    SELECT org_id INTO v_org_id
    FROM workspaces
    WHERE id = p_workspace_id;
  END IF;

  -- Step 3: Org membership check
  IF v_org_id IS NOT NULL THEN
    SELECT om.role_id, om.is_owner, om.is_active
    INTO v_role_id, v_is_owner, v_is_active
    FROM org_members om
    WHERE om.user_id = p_user_id AND om.org_id = v_org_id;

    IF FOUND THEN
      IF v_is_active = false THEN
        RETURN jsonb_build_object(
          'is_platform_owner', false,
          'is_owner', false,
          'is_active', false,
          'role_slug', null,
          'permission_keys', '[]'::jsonb
        );
      END IF;

      IF v_is_owner THEN
        SELECT r.slug INTO v_role_slug FROM roles r WHERE r.id = v_role_id;
        RETURN jsonb_build_object(
          'is_platform_owner', false,
          'is_owner', true,
          'is_active', true,
          'role_slug', v_role_slug,
          'permission_keys', (
            SELECT jsonb_agg(key) FROM permissions
          )
        );
      END IF;

      IF v_role_id IS NOT NULL THEN
        SELECT r.slug INTO v_role_slug FROM roles r WHERE r.id = v_role_id;
        SELECT array_agg(p.key) INTO v_permission_keys
        FROM role_permissions rp
        JOIN permissions p ON p.id = rp.permission_id
        WHERE rp.role_id = v_role_id;

        IF v_permission_keys IS NOT NULL AND array_length(v_permission_keys, 1) > 0 THEN
          RETURN jsonb_build_object(
            'is_platform_owner', false,
            'is_owner', false,
            'is_active', true,
            'role_slug', v_role_slug,
            'permission_keys', to_jsonb(v_permission_keys)
          );
        END IF;
      END IF;
    END IF;
  END IF;

  -- Step 4: Workspace-level membership
  IF p_workspace_id IS NOT NULL THEN
    SELECT wm.role_id INTO v_role_id
    FROM workspace_memberships wm
    WHERE wm.user_id = p_user_id AND wm.workspace_id = p_workspace_id;

    IF v_role_id IS NOT NULL THEN
      SELECT r.slug INTO v_role_slug FROM roles r WHERE r.id = v_role_id;
      SELECT array_agg(p.key) INTO v_permission_keys
      FROM role_permissions rp
      JOIN permissions p ON p.id = rp.permission_id
      WHERE rp.role_id = v_role_id;

      RETURN jsonb_build_object(
        'is_platform_owner', false,
        'is_owner', false,
        'is_active', true,
        'role_slug', v_role_slug,
        'permission_keys', COALESCE(to_jsonb(v_permission_keys), '[]'::jsonb)
      );
    END IF;
  END IF;

  -- Step 5: Default deny
  RETURN jsonb_build_object(
    'is_platform_owner', false,
    'is_owner', false,
    'is_active', true,
    'role_slug', null,
    'permission_keys', '[]'::jsonb
  );
END;
$$;


--
-- Name: rollup_usage_summaries(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rollup_usage_summaries(p_period_type text DEFAULT 'daily'::text, p_lookback_days integer DEFAULT 2) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count INT := 0;
  v_period_start DATE;
  v_period_end DATE;
  v_since TIMESTAMPTZ;
BEGIN
  v_since := NOW() - (p_lookback_days || ' days')::INTERVAL;

  IF p_period_type = 'daily' THEN
    -- Aggregate daily summaries
    INSERT INTO usage_summaries (workspace_id, period_type, period_start, metric, total, count)
    SELECT
      workspace_id,
      'daily',
      DATE_TRUNC('day', created_at)::DATE AS period_start,
      event_type AS metric,
      COALESCE(SUM(quantity), 0) AS total,
      COUNT(*) AS count
    FROM usage_events
    WHERE created_at >= v_since
    GROUP BY workspace_id, DATE_TRUNC('day', created_at)::DATE, event_type
    ON CONFLICT (workspace_id, period_type, period_start, metric)
    DO UPDATE SET
      total = EXCLUDED.total,
      count = EXCLUDED.count,
      updated_at = NOW();

    GET DIAGNOSTICS v_count = ROW_COUNT;

  ELSIF p_period_type = 'monthly' THEN
    -- Aggregate monthly summaries
    INSERT INTO usage_summaries (workspace_id, period_type, period_start, metric, total, count)
    SELECT
      workspace_id,
      'monthly',
      DATE_TRUNC('month', created_at)::DATE AS period_start,
      event_type AS metric,
      COALESCE(SUM(quantity), 0) AS total,
      COUNT(*) AS count
    FROM usage_events
    WHERE created_at >= DATE_TRUNC('month', NOW() - (p_lookback_days || ' days')::INTERVAL)
    GROUP BY workspace_id, DATE_TRUNC('month', created_at)::DATE, event_type
    ON CONFLICT (workspace_id, period_type, period_start, metric)
    DO UPDATE SET
      total = EXCLUDED.total,
      count = EXCLUDED.count,
      updated_at = NOW();

    GET DIAGNOSTICS v_count = ROW_COUNT;
  END IF;

  RETURN v_count;
END;
$$;


--
-- Name: search_code_examples(extensions.vector, text, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_code_examples(query_embedding extensions.vector, query_text text, filter_workspace_id uuid, match_count integer DEFAULT 10, filter_language text DEFAULT NULL::text) RETURNS TABLE(id uuid, code_block text, language text, summary text, source_path text, vector_similarity double precision, keyword_rank double precision, combined_score double precision)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  ts_query tsquery;
BEGIN
  SET LOCAL hnsw.iterative_scan = 'relaxed_order';
  SET LOCAL hnsw.max_scan_tuples = 10000;

  BEGIN
    ts_query := plainto_tsquery('english', query_text);
  EXCEPTION WHEN OTHERS THEN
    ts_query := NULL;
  END;

  RETURN QUERY
  SELECT
    bce.id,
    bce.code_block,
    bce.language,
    bce.summary,
    bce.source_path,
    CASE WHEN bce.embedding IS NOT NULL
      THEN 1 - (bce.embedding <=> query_embedding)
      ELSE 0.0
    END AS vector_similarity,
    CASE WHEN ts_query IS NOT NULL AND bce.fts @@ ts_query
      THEN ts_rank_cd(bce.fts, ts_query, 32)
      ELSE 0.0
    END AS keyword_rank,
    -- Combined: 60% vector + 40% keyword (code search favors exact matches)
    (CASE WHEN bce.embedding IS NOT NULL
      THEN (1 - (bce.embedding <=> query_embedding)) * 0.6
      ELSE 0.0
    END)
    + (CASE WHEN ts_query IS NOT NULL AND bce.fts @@ ts_query
      THEN ts_rank_cd(bce.fts, ts_query, 32) * 0.4
      ELSE 0.0
    END) AS combined_score
  FROM brain_code_examples bce
  WHERE bce.workspace_id = filter_workspace_id
    AND (filter_language IS NULL OR bce.language = filter_language)
    AND (
      (bce.embedding IS NOT NULL AND 1 - (bce.embedding <=> query_embedding) > 0.3)
      OR (ts_query IS NOT NULL AND bce.fts @@ ts_query)
    )
  ORDER BY combined_score DESC
  LIMIT match_count;
END;
$$;


--
-- Name: FUNCTION search_code_examples(query_embedding extensions.vector, query_text text, filter_workspace_id uuid, match_count integer, filter_language text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.search_code_examples(query_embedding extensions.vector, query_text text, filter_workspace_id uuid, match_count integer, filter_language text) IS 'Search code examples extracted from brain manifest skills using hybrid vector + keyword search.';


--
-- Name: search_knowledge_items(uuid, text, integer, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_knowledge_items(p_workspace_id uuid, p_embedding text, p_limit integer DEFAULT 10, p_source_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(id uuid, source_id uuid, title text, section_title text, content text, metadata jsonb, similarity double precision)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    ki.id,
    ki.source_id,
    ki.title,
    ki.section_title,
    ki.content,
    ki.metadata,
    1 - (ki.embedding <=> p_embedding::vector) AS similarity
  FROM knowledge_items ki
  WHERE ki.workspace_id = p_workspace_id
    AND ki.embedding IS NOT NULL
    AND (p_source_ids IS NULL OR ki.source_id = ANY(p_source_ids))
  ORDER BY ki.embedding <=> p_embedding::vector
  LIMIT p_limit;
END;
$$;


--
-- Name: seed_org_roles(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_org_roles() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_system_role RECORD;
  v_new_role_id uuid;
BEGIN
  -- Loop through the 4 standard system roles
  FOR v_system_role IN
    SELECT id, name, slug, description
    FROM roles
    WHERE is_system = true
      AND org_id IS NULL
      AND slug IN ('viewer', 'member', 'admin', 'owner')
    ORDER BY slug
  LOOP
    -- Create org-scoped role
    INSERT INTO roles (name, slug, description, org_id, is_system)
    VALUES (
      v_system_role.name,
      v_system_role.slug,
      v_system_role.description,
      NEW.id,
      false  -- org-scoped roles are not system roles
    )
    ON CONFLICT (slug, org_id) DO NOTHING
    RETURNING id INTO v_new_role_id;

    -- If role was created (not already existing), seed its permissions
    IF v_new_role_id IS NOT NULL THEN
      INSERT INTO role_permissions (role_id, permission_id)
      SELECT v_new_role_id, rp.permission_id
      FROM role_permissions rp
      WHERE rp.role_id = v_system_role.id;
    END IF;
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- Name: set_ai_job_expires_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_ai_job_expires_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.expires_at = NEW.created_at + make_interval(secs => NEW.schedule_to_start_ms / 1000.0);
  RETURN NEW;
END;
$$;


--
-- Name: set_completed_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_completed_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Task moving to done: set completed_at if not already set
  IF NEW.status = 'done' AND NEW.completed_at IS NULL THEN
    NEW.completed_at := now();
  END IF;

  -- Task reopened from done: clear completed_at
  IF OLD.status = 'done' AND NEW.status != 'done' THEN
    NEW.completed_at := NULL;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: set_memory_ttl(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_memory_ttl() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_plan text;
BEGIN
  IF NEW.expires_at IS NOT NULL THEN
    RETURN NEW;
  END IF;

  v_plan := 'build';

  NEW.expires_at := CASE v_plan
    WHEN 'free' THEN now() + interval '30 days'
    WHEN 'build' THEN now() + interval '1 year'
    WHEN 'pro' THEN now() + interval '1 year'
    WHEN 'team' THEN NULL
    ELSE now() + interval '1 year'
  END;

  RETURN NEW;
END;
$$;


