--
-- Name: sum_usage_events(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sum_usage_events(p_workspace_id uuid, p_since timestamp with time zone) RETURNS TABLE(event_type text, total numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT event_type, SUM(quantity)::numeric AS total
  FROM usage_events
  WHERE workspace_id = p_workspace_id
    AND created_at >= p_since
  GROUP BY event_type;
$$;


--
-- Name: sync_dependency_blocked_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_dependency_blocked_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  dep_id uuid;
  all_done boolean;
  dependent_task record;
BEGIN
  -- Case 1: depends_on changed on this task — check if it should be blocked
  IF TG_OP = 'UPDATE' AND NEW.depends_on IS DISTINCT FROM OLD.depends_on THEN
    IF array_length(NEW.depends_on, 1) IS NOT NULL AND array_length(NEW.depends_on, 1) > 0 THEN
      SELECT NOT EXISTS (
        SELECT 1 FROM tasks
        WHERE id = ANY(NEW.depends_on) AND status != 'done'
      ) INTO all_done;

      IF NOT all_done THEN
        -- Auto-block: set blocked metadata
        NEW.metadata = jsonb_set(
          COALESCE(NEW.metadata, '{}'::jsonb),
          '{blocked}', 'true'
        );
        NEW.metadata = jsonb_set(
          NEW.metadata,
          '{blocked_reason}', '"Waiting on dependency"'
        );
        NEW.metadata = jsonb_set(
          NEW.metadata,
          '{blocked_at}', to_jsonb(now()::text)
        );
        NEW.metadata = jsonb_set(
          NEW.metadata,
          '{blocked_by}', '"system"'
        );
      ELSE
        -- All deps are done — clear auto-block if system-blocked
        IF (NEW.metadata->>'blocked_by') = 'system' THEN
          NEW.metadata = NEW.metadata - 'blocked' - 'blocked_at' - 'blocked_reason' - 'blocked_by';
          NEW.metadata = jsonb_set(
            COALESCE(NEW.metadata, '{}'::jsonb),
            '{auto_unblocked_at}', to_jsonb(now()::text)
          );
        END IF;
      END IF;
    END IF;
  END IF;

  -- Case 2: status changed to done — check downstream tasks
  IF TG_OP = 'UPDATE' AND NEW.status = 'done' AND OLD.status != 'done' THEN
    FOR dependent_task IN
      SELECT id, depends_on, metadata FROM tasks
      WHERE NEW.id = ANY(depends_on)
        AND (metadata->>'blocked_by') = 'system'
    LOOP
      SELECT NOT EXISTS (
        SELECT 1 FROM tasks
        WHERE id = ANY(dependent_task.depends_on) AND status != 'done'
      ) INTO all_done;

      IF all_done THEN
        UPDATE tasks SET
          metadata = (COALESCE(dependent_task.metadata, '{}'::jsonb)
            - 'blocked' - 'blocked_at' - 'blocked_reason' - 'blocked_by')
            || jsonb_build_object('auto_unblocked_at', now()::text)
        WHERE id = dependent_task.id;
      END IF;
    END LOOP;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: task_inherit_workspace_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.task_inherit_workspace_id() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Only act when project_id is set and workspace_id is null
  IF NEW.project_id IS NOT NULL AND NEW.workspace_id IS NULL THEN
    SELECT workspace_id INTO NEW.workspace_id
    FROM projects
    WHERE id = NEW.project_id;
  END IF;
  RETURN NEW;
END;
$$;


