-- Name: touch_memories(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_memories(memory_ids uuid[]) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  UPDATE agent_memory
  SET access_count = access_count + 1,
      last_accessed_at = now()
  WHERE id = ANY(memory_ids);
$$;


--
-- Name: transfer_org_ownership(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_org_ownership(p_from_user uuid, p_to_user uuid, p_org_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_member_id UUID;
  v_target_member_id UUID;
BEGIN
  -- 1. Verify caller is an active owner of this org
  SELECT id INTO v_caller_member_id
    FROM org_members
   WHERE user_id = p_from_user
     AND org_id  = p_org_id
     AND is_owner = true;

  IF v_caller_member_id IS NULL THEN
    RAISE EXCEPTION 'Caller is not an owner of org %', p_org_id;
  END IF;

  -- 2. Verify target is an active, non-owner member of this org
  SELECT id INTO v_target_member_id
    FROM org_members
   WHERE user_id   = p_to_user
     AND org_id    = p_org_id
     AND is_active = true
     AND is_owner  = false;

  IF v_target_member_id IS NULL THEN
    RAISE EXCEPTION 'Target user is not an eligible member of org %', p_org_id;
  END IF;

  -- 3. Atomic swap: revoke from caller, grant to target
  UPDATE org_members SET is_owner = false WHERE id = v_caller_member_id;
  UPDATE org_members SET is_owner = true  WHERE id = v_target_member_id;

  -- 4. Sync user_roles (best-effort backward compat)
  UPDATE user_roles SET role = 'admin' WHERE user_id = p_from_user;
  UPDATE user_roles SET role = 'owner' WHERE user_id = p_to_user;
END;
$$;


--
-- Name: FUNCTION transfer_org_ownership(p_from_user uuid, p_to_user uuid, p_org_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.transfer_org_ownership(p_from_user uuid, p_to_user uuid, p_org_id uuid) IS 'Atomically transfers org ownership from one user to another. SECURITY DEFINER: mutates rows for two users in one transaction; caller verified via p_from_user + is_owner check.';


