--
-- Name: user_admin_org_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_admin_org_ids() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- Legacy path
  SELECT org_id FROM org_memberships
  WHERE user_id = auth.uid() AND role IN ('owner', 'admin')
  UNION
  -- RBAC v2 path: org owners
  SELECT org_id FROM org_members
  WHERE user_id = auth.uid() AND is_owner = true AND is_active = true
  UNION
  -- RBAC v2 path: org members with settings:manage permission
  SELECT om.org_id FROM org_members om
  WHERE om.user_id = auth.uid()
    AND om.is_active = true
    AND EXISTS (
      SELECT 1 FROM role_permissions rp
      JOIN permissions p ON p.id = rp.permission_id
      WHERE rp.role_id = om.role_id AND p.key = 'settings:manage'
    );
$$;


--
-- Name: user_has_permission(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_has_permission(p_user_id uuid, p_workspace_id uuid, p_permission_key text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_role_id uuid;
  v_has_permission boolean;
BEGIN
  -- Step 1: Platform admin (legacy user_roles bridge)
  IF EXISTS (
    SELECT 1 FROM user_roles
    WHERE user_id = p_user_id AND role = 'owner' AND is_active = true
  ) THEN
    RETURN true;
  END IF;

  -- Step 2: Resolve workspace → org_id
  SELECT org_id INTO v_org_id
  FROM workspaces
  WHERE id = p_workspace_id;

  -- Step 3: Org membership
  IF v_org_id IS NOT NULL THEN
    -- Check if org owner
    IF EXISTS (
      SELECT 1 FROM org_members
      WHERE user_id = p_user_id AND org_id = v_org_id
        AND is_owner = true AND is_active = true
    ) THEN
      RETURN true;
    END IF;

    -- Check org-level role permissions
    SELECT om.role_id INTO v_role_id
    FROM org_members om
    WHERE om.user_id = p_user_id AND om.org_id = v_org_id AND om.is_active = true;

    IF v_role_id IS NOT NULL THEN
      SELECT EXISTS (
        SELECT 1 FROM role_permissions rp
        JOIN permissions p ON p.id = rp.permission_id
        WHERE rp.role_id = v_role_id AND p.key = p_permission_key
      ) INTO v_has_permission;
      IF v_has_permission THEN RETURN true; END IF;
    END IF;
  END IF;

  -- Step 4: Workspace-level role
  SELECT wm.role_id INTO v_role_id
  FROM workspace_memberships wm
  WHERE wm.user_id = p_user_id AND wm.workspace_id = p_workspace_id;

  IF v_role_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM role_permissions rp
      JOIN permissions p ON p.id = rp.permission_id
      WHERE rp.role_id = v_role_id AND p.key = p_permission_key
    ) INTO v_has_permission;
    IF v_has_permission THEN RETURN true; END IF;
  END IF;

  -- Step 5: Default deny
  RETURN false;
END;
$$;


--
-- Name: user_org_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_org_ids() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT org_id FROM org_memberships WHERE user_id = auth.uid()
$$;


--
-- Name: user_workspace_ids(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_workspace_ids(uid uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- Platform admin via user_roles: all workspaces in their org(s)
  SELECT w.id
  FROM workspaces w
  WHERE w.org_id IN (
    SELECT ur.org_id
    FROM user_roles ur
    WHERE ur.user_id = uid
      AND ur.role IN ('owner', 'admin')
      AND ur.is_active = true
  )
  UNION
  -- Org owner/admin via org_members: all workspaces in their org(s)
  SELECT w.id
  FROM workspaces w
  WHERE w.org_id IN (
    SELECT om.org_id
    FROM org_members om
    WHERE om.user_id = uid
      AND om.is_active = true
      AND (om.is_owner = true OR EXISTS (
        SELECT 1 FROM role_permissions rp
        JOIN permissions p ON p.id = rp.permission_id
        WHERE rp.role_id = om.role_id AND p.key = 'settings:manage'
      ))
  )
  UNION
  -- Explicit workspace membership
  SELECT wm.workspace_id
  FROM workspace_memberships wm
  WHERE wm.user_id = uid;
$$;


