--
-- Name: access_codes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.access_codes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    created_by uuid NOT NULL,
    redeemed_by uuid,
    redeemed_at timestamp with time zone,
    revoked_at timestamp with time zone,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone,
    duration text,
    plan text DEFAULT 'builder'::text NOT NULL,
    max_uses integer DEFAULT 1 NOT NULL,
    uses integer DEFAULT 0 NOT NULL,
    CONSTRAINT access_codes_duration_check CHECK ((duration = ANY (ARRAY['1_week'::text, '1_month'::text, '3_months'::text, '6_months'::text, '1_year'::text, 'unlimited'::text]))),
    CONSTRAINT access_codes_plan_check CHECK ((plan = ANY (ARRAY['builder'::text, 'pro'::text, 'unlimited'::text]))),
    CONSTRAINT expires_consistent CHECK (((duration IS NULL) OR (duration = 'unlimited'::text) OR (expires_at IS NOT NULL)))
);


--
-- Name: activity_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.activity_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_type text NOT NULL,
    severity public.severity_level DEFAULT 'info'::public.severity_level NOT NULL,
    source text,
    title text NOT NULL,
    details jsonb,
    task_id uuid,
    agent_id text,
    actor_user_id uuid,
    workspace_id uuid,
    acknowledged boolean DEFAULT false,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    acknowledged_at timestamp with time zone,
    user_id uuid DEFAULT auth.uid(),
    ip_address inet,
    before_state jsonb,
    after_state jsonb,
    resource_type text,
    resource_id text,
    memory_processed_at timestamp with time zone
);


