    fts tsvector GENERATED ALWAYS AS (to_tsvector('english'::regconfig, ((((COALESCE(key, ''::text) || ' '::text) || COALESCE(content, ''::text)) || ' '::text) || COALESCE(tags, ''::text)))) STORED,
    is_core boolean DEFAULT false NOT NULL,
