    CONSTRAINT agent_memory_embedding_status_check CHECK ((embedding_status = ANY (ARRAY['none'::text, 'pending'::text, 'complete'::text, 'failed'::text]))),
    CONSTRAINT agent_memory_importance_score_check CHECK (((importance_score >= (0)::double precision) AND (importance_score <= (1)::double precision))),
    CONSTRAINT agent_memory_memory_type_check CHECK ((memory_type = ANY (ARRAY['fact'::text, 'preference'::text, 'decision'::text, 'context'::text, 'episode'::text, 'handoff'::text])))
);


