--
-- Name: VIEW execution_logs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.execution_logs IS 'Read-only compatibility view over job_logs. Remove next release.';


--
-- Name: execution_queue; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.execution_queue WITH (security_invoker='true') AS
 SELECT id,
    workspace_id,
    requester_id AS user_id,
    org_id,
    COALESCE(target_type, 'external'::text) AS target_type,
        CASE
            WHEN (target_type = 'task'::text) THEN target_id
            ELSE NULL::uuid
        END AS task_id,
        CASE
            WHEN (target_type = 'project'::text) THEN target_id
            ELSE NULL::uuid
        END AS project_id,
        CASE (status)::text
            WHEN 'streaming'::text THEN 'processing'::text
            ELSE (status)::text
        END AS status,
    priority,
    claimed_at,
    started_at,
    completed_at,
        CASE
            WHEN (status = 'failed'::public.ai_job_status) THEN completed_at
            ELSE NULL::timestamp with time zone
        END AS failed_at,
    COALESCE((metadata ->> 'agent_id'::text), 'rick'::text) AS agent_id,
    worker_id,
    token_budget,
    tokens_used,
    start_to_close_ms AS timeout_ms,
    attempt AS retry_count,
    max_attempts AS max_retries,
    (metadata ->> 'system_prompt'::text) AS system_prompt,
    tools,
    COALESCE((metadata -> 'context'::text), '{}'::jsonb) AS context,
    (metadata ->> 'outcome'::text) AS outcome,
    (last_error ->> 'message'::text) AS error_message,
    (last_error ->> 'code'::text) AS error_code,
    metadata,
    created_at,
    updated_at
   FROM public.ai_job_queue j
  WHERE (runner = 'server'::text);


--
-- Name: VIEW execution_queue; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.execution_queue IS 'Read-only compatibility view over ai_job_queue (runner = server). Remove next release.';


