-- Name: workspaces; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workspaces (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    name text NOT NULL,
    slug text NOT NULL,
    description text DEFAULT ''::text,
    icon text DEFAULT '🏠'::text,
    color_scheme text DEFAULT 'default'::text,
    is_default boolean DEFAULT false NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    repo_url text,
    repo_provider text DEFAULT 'github'::text NOT NULL,
    repo_path text,
    repo_connected_at timestamp with time zone,
    github_installation_id bigint,
    status text DEFAULT 'draft'::text NOT NULL,
    github_default_branch text DEFAULT 'main'::text,
    github_settings jsonb DEFAULT '{"auto_pr": "draft_on_push", "pr_strategy": "per_project", "branch_naming": {"prefix": "celune", "separator": "/", "slug_source": "project_name", "include_assignee": true}, "webhook_events": false, "auto_sync_on_push": true, "default_reviewers": [], "agent_code_context": true, "stale_pr_warning_days": 7, "rebase_threshold_commits": 20}'::jsonb,
    parent_workspace_id uuid,
    portfolio_cors_origins text[] DEFAULT '{}'::text[],
    trial_token_budget integer DEFAULT 50000 NOT NULL,
    trial_tokens_used integer DEFAULT 0 NOT NULL,
    brain_settings jsonb DEFAULT '{"reranking": false, "hybrid_search": true, "vector_weight": 0.7, "keyword_weight": 0.3, "embedding_model": "gte-small", "auto_crawl_interval_hours": 24}'::jsonb,
    ai_token_limit_monthly bigint,
    ai_requests_per_minute integer,
    CONSTRAINT chk_main_no_parent CHECK ((NOT ((is_default = true) AND (parent_workspace_id IS NOT NULL)))),
    CONSTRAINT workspaces_ai_requests_per_minute_check CHECK (((ai_requests_per_minute IS NULL) OR (ai_requests_per_minute >= 0))),
    CONSTRAINT workspaces_ai_token_limit_monthly_check CHECK (((ai_token_limit_monthly IS NULL) OR (ai_token_limit_monthly >= 0))),
    CONSTRAINT workspaces_repo_provider_check CHECK ((repo_provider = ANY (ARRAY['github'::text, 'gitlab'::text, 'bitbucket'::text]))),
    CONSTRAINT workspaces_status_check CHECK ((status = ANY (ARRAY['active'::text, 'draft'::text, 'archived'::text, 'deprecated'::text])))
);


--
-- Name: COLUMN workspaces.repo_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.workspaces.repo_url IS 'Full GitHub repository URL, e.g. https://github.com/org/repo. Null if not yet connected.';


--
