--

COMMENT ON COLUMN public.workspaces.repo_path IS 'Path within the repository root. Use ''/'' or NULL for standalone repos. Use ''apps/looq'' for monorepo sub-folders.';


--
-- Name: COLUMN workspaces.repo_connected_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.workspaces.repo_connected_at IS 'Timestamp when the repository connection was established. NULL means connection is pending or was deferred.';


--
