--
-- Name: dot_voter_items Authenticated users can read items for their rooms; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Authenticated users can read items for their rooms" ON public.dot_voter_items FOR SELECT TO authenticated USING ((room_id IN ( SELECT dot_voter_rooms.id
   FROM public.dot_voter_rooms
  WHERE (dot_voter_rooms.workspace_id IN ( SELECT workspaces.id
           FROM public.workspaces
          WHERE (workspaces.org_id IN ( SELECT org_members.org_id
                   FROM public.org_members
                  WHERE (org_members.user_id = auth.uid()))))))));


--
-- Name: claude_usage Authenticated users read own claude_usage; Type: POLICY; Schema: public; Owner: -
--

