     JOIN public.org_memberships om ON (((om.org_id = w.org_id) AND (om.user_id = wm.user_id))))
  WHERE ((wm.workspace_id = workspace_invitations.workspace_id) AND (wm.user_id = auth.uid()) AND (om.role = ANY (ARRAY['owner'::text, 'admin'::text]))))));


